#include "stdlib/blas/ext/base/ccusome.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/real.h"
#include "stdlib/complex/float32/imag.h"
#include "stdlib/blas/base/shared.h"
#include <stdbool.h>

/**
* Cumulatively tests whether at least `k` elements in a single-precision complex floating-point strided array are truthy.
*
* @param N         number of indexed elements
* @param k         minimum number of truthy elements
* @param X         input array
* @param strideX   stride length for X
* @param Out       output array
* @param strideOut stride length for Out
*/
void API_SUFFIX(stdlib_strided_ccusome)( const CBLAS_INT N, const CBLAS_INT k, const stdlib_complex64_t *X, const CBLAS_INT strideX, bool *Out, const CBLAS_INT strideOut ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	CBLAS_INT oo = stdlib_strided_stride2offset( N, strideOut );
	API_SUFFIX(stdlib_strided_ccusome_ndarray)( N, k, X, strideX, ox, Out, strideOut, oo );
}

/**
* Cumulatively tests whether at least `k` elements in a single-precision complex floating-point strided array are truthy using alternative indexing semantics.
*
* @param N         number of indexed elements
* @param k         minimum number of truthy elements
* @param X         input array
* @param strideX   stride length for X
* @param offsetX   starting index for X
* @param Out       output array
* @param strideOut stride length for Out
* @param offsetOut starting index for Out
*/
void API_SUFFIX(stdlib_strided_ccusome_ndarray)( const CBLAS_INT N, const CBLAS_INT k, const stdlib_complex64_t *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, bool *Out, const CBLAS_INT strideOut, const CBLAS_INT offsetOut ) {
	stdlib_complex64_t v;
	CBLAS_INT cnt;
	CBLAS_INT ix;
	CBLAS_INT io;
	CBLAS_INT i;
	float re;
	float im;
	bool flg;

	if ( N <= 0 ) {
		return;
	}
	flg = false;
	cnt = k;
	ix = offsetX;
	io = offsetOut;
	for ( i = 0; i < N; i++ ) {
		v = X[ ix ];
		re = stdlib_complex64_real( v );
		im = stdlib_complex64_imag( v );
		if ( !flg && ( ( re != 0.0f && !stdlib_base_is_nanf( re ) ) || ( im != 0.0f && !stdlib_base_is_nanf( im ) ) ) ) {
			cnt -= 1;
			if ( cnt <= 0 ) {
				flg = true;
			}
		}
		Out[ io ] = flg;
		ix += strideX;
		io += strideOut;
	}
	return;
}
